"""patch_marking_qol.py — QOL-V1 + PROVENANCE-V1 + ORPHAN-SCAN-V1 (2026-07-04).

1. RENAME in edit mode: a name field in the pending bar (autocomplete),
   prefilled; change it + confirm = the marking moves to the new name
   (delete old + add new, atomically from the user's perspective).
2. FRESH LM CACHE: every LM created in the session immediately joins the
   autocomplete and the known-name resolution (no stale-list surprises).
3. PROVENANCE AUTO (server): deleting a marking drops the cam from the
   LM's source_cameras; if no source remains the LM's xyz is quarantined
   (the fossil detector's blind spot, closed). CI gains an orphan scan
   (warning) — first run reveals ~150 HISTORICAL orphans accumulated
   silently over the project (a review pile, not a bug).
   NOTE: renaming a single-sourced LM's marking quarantines the OLD LM's
   xyz by design — the ray that justified it was just relabeled.
4. IMAGE ADJUST (◐ adjust button, top right): exposure / highlights /
   shadows / brightness / contrast / blackpoint / texture / clarity —
   pure display (SVG filter on the frame element only; markers, loupe
   colors and DATA untouched). Reset button + auto-reset on close.

Live-tested headless: filter on/off, 33-pt tone curve, rename round-trip
(pixel bit-identical after A->B->A), session cache, zero JS errors.
Idempotent. Backups: .bak_qol. Restart server + hard refresh.
"""
import shutil, sys

P = 'tools/server.py'
s = open(P).read()
if 'PROVENANCE-V1' in s:
    print('server: deja patche')
else:
    shutil.copy(P, P + '.bak_qol')
    old = '            print(f"Deleted pixel {lm_name} from {cam_name}")\n            self.send_json({\'ok\': True})'
    assert old in s, 'anchor server'
    s = s.replace(old, '            # [PROVENANCE-V1] keep landmarks_meta coherent: a deleted marking\n            # removes this cam from the LM\'s source_cameras; if no source\n            # remains, the xyz is a fossil-blind-spot orphan -> quarantine.\n            prov_note = None\n            meta = md.landmarks_meta.get(lm_name)\n            if meta and cam_name in (meta.get(\'source_cameras\') or []):\n                new_src = [c for c in meta[\'source_cameras\'] if c != cam_name]\n                if new_src:\n                    md.update_landmark(lm_name, md.landmarks.get(lm_name),\n                                       source_cameras=new_src,\n                                       error_m=meta.get(\'error_m\'))\n                    prov_note = f\'source dropped ({len(new_src)} left)\'\n                else:\n                    md.update_landmark(lm_name, None, source_cameras=[], error_m=None)\n                    prov_note = \'orphaned -> quarantined (xyz=None)\'\n                print(f"Provenance: {lm_name}: {prov_note}")\n            print(f"Deleted pixel {lm_name} from {cam_name}")\n            self.send_json({\'ok\': True, \'provenance\': prov_note})', 1)
    open(P, 'w').write(s)
    print('tools/server.py: PROVENANCE-V1')

P = 'tools/ci_healthcheck.py'
s = open(P).read()
if 'ORPHAN-SCAN-V1' in s:
    print('ci: deja patche')
else:
    shutil.copy(P, P + '.bak_qol')
    old = "        else:\n            print('✓ fossils: none')\n    except Exception as e:\n        print(f'⚠ fossil scan failed: {e}')"
    assert old in s, 'anchor ci'
    s = s.replace(old, old + "\n\n    # ── 7. orphan scan (WARNING) [ORPHAN-SCAN-V1] ────────────────────────\n    # LM with xyz whose NO source cam still has a marking on it: the fossil\n    # detector's documented blind spot (e.g. after renaming markings).\n    try:\n        import gtamapdata as _md\n        orphans = []\n        for _lm, _xyz in _md.landmarks.items():\n            if _xyz is None:\n                continue\n            _src = (_md.landmarks_meta.get(_lm) or {}).get('source_cameras', []) or []\n            # empty sources = derived/procedural LM (rigid bodies, mast levels,\n            # z-constraint solves) — legitimate. Orphan = sources LISTED but\n            # none of them still has a marking (e.g. after a rename).\n            _real = [_c for _c in _src if not str(_c).startswith('(legacy')]\n            if _real and not any(_md.pixels.get(_c, {}).get(_lm) is not None for _c in _real):\n                orphans.append(_lm)\n        if orphans:\n            print(f'⚠ orphans: {len(orphans)} LM(s) with xyz but no source marking left')\n            for _o in orphans[:5]:\n                print(f'      {_o}')\n            if len(orphans) > 5:\n                print(f'      ... +{len(orphans)-5} more')\n        else:\n            print('✓ orphans: none')\n    except Exception as e:\n        print(f'⚠ orphan scan failed: {e}')", 1)
    open(P, 'w').write(s)
    print('tools/ci_healthcheck.py: ORPHAN-SCAN-V1')

P = 'tools/calib.html'
s = open(P).read()
if 'QOL-V1' in s:
    print('calib: deja patche'); sys.exit(0)
shutil.copy(P, P + '.bak_qol')
assert 'DELETE-BTN-V1' in s, 'prerequis: chaine marking complete'
i = s.rindex('</body>')
s = s[:i] + '\n<!-- [QOL-V1] image adjust: SVG tone filter + panel -->\n<svg width="0" height="0" style="position:absolute">\n  <filter id="mkadj" x="0" y="0" width="100%" height="100%">\n    <feComponentTransfer id="mkadj-tone" result="tone">\n      <feFuncR type="table" tableValues="0 1"/>\n      <feFuncG type="table" tableValues="0 1"/>\n      <feFuncB type="table" tableValues="0 1"/>\n    </feComponentTransfer>\n    <feGaussianBlur in="tone" stdDeviation="1.5" result="btex"/>\n    <feComposite id="mkadj-tex" in="tone" in2="btex" operator="arithmetic" k1="0" k2="1" k3="0" k4="0" result="tex"/>\n    <feGaussianBlur in="tex" stdDeviation="10" result="bcla"/>\n    <feComposite id="mkadj-cla" in="tex" in2="bcla" operator="arithmetic" k1="0" k2="1" k3="0" k4="0"/>\n  </filter>\n</svg>\n<div id="mkadj-panel" style="display:none;position:fixed;right:14px;top:64px;z-index:390;width:230px;\n  background:#101016f2;border:1px solid var(--border,#2a2a33);border-radius:9px;padding:10px 12px;\n  box-shadow:0 8px 28px #000c;font-family:var(--mono,monospace)">\n  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:7px">\n    <span style="font-size:9px;letter-spacing:.12em;color:var(--dim,#666)">IMAGE ADJUST</span>\n    <div>\n      <button id="mkadj-reset" style="background:none;border:none;color:var(--mid,#999);cursor:pointer;font-size:12px" title="reset all">↺</button>\n      <button id="mkadj-close" style="background:none;border:none;color:var(--mid,#999);cursor:pointer;font-size:12px">✕</button>\n    </div>\n  </div>\n  <div id="mkadj-sliders"></div>\n  <div style="font-size:8.5px;color:var(--dim,#555);margin-top:6px">display only — never touches the data · auto-reset on close</div>\n</div>\n\n' + s[i:]
old = '             font-family:JetBrains Mono,monospace">⊕ cams</button>'
assert old in s, 'anchor bouton cams'
s = s.replace(old, old + '\n    <button id="btn-mkadj" onclick="window._mkAdjToggle()" style="position:absolute;top:12px;right:270px;z-index:30;\n             background:#1a1a22cc;border:1px solid #333;color:#999;padding:6px 12px;border-radius:6px;cursor:pointer;font-size:12px;\n             font-family:JetBrains Mono,monospace">◐ adjust</button>', 1)
i = s.rindex('</body>')
s = s[:i] + '\n<script>\n// ══ [QOL-V1] marking quality-of-life: rename, fresh LM cache, image adjust ══\n(() => {\n  // ── #2: fresh LM cache shared by every autocomplete ──\n  window._mkKnownNew = new Set();\n  window._mkRegisterLm = function(name) {\n    if (window._mkKnownNew.has(name)) return;\n    window._mkKnownNew.add(name);\n    const dl = document.getElementById(\'mk-add-list\');\n    if (dl) {\n      const o = document.createElement(\'option\');\n      o.value = name;\n      dl.appendChild(o);\n    }\n  };\n\n  // ── #1: rename field in the pending confirm bar ──\n  const bar = document.getElementById(\'mk-confirm\');\n  const renameWrap = document.createElement(\'div\');\n  renameWrap.style.cssText = \'margin:5px 0 2px\';\n  renameWrap.innerHTML = \'<input id="mk-rename" list="mk-add-list" type="text" \' +\n    \'style="width:100%;box-sizing:border-box;font-family:inherit;font-size:10.5px;background:#ffffff0a;\' +\n    \'border:1px solid var(--border,#333);color:var(--text,#ddd);padding:3px 7px;border-radius:4px;outline:none" \' +\n    \'title="change the LM name — applied on confirm">\';\n  bar.insertBefore(renameWrap, bar.querySelector(\'#mk-confirm-delta\').nextSibling);\n  const renameInput = document.getElementById(\'mk-rename\');\n  renameInput.addEventListener(\'keydown\', e => {\n    if (e.key === \'Enter\') { e.preventDefault(); e.stopPropagation(); window._mkConfirmPending(); }\n    e.stopPropagation();   // les fleches editent le texte, pas le nudge\n  });\n\n  // pre-remplir a l\'entree en pending\n  const _enter = window._mkEnterPending;\n  window._mkEnterPending = function(d) {\n    _enter(d);\n    renameInput.value = d.lm;\n  };\n\n  // wrapper le confirm: si le nom a change -> delete old (move) + add new\n  const _confirm = window._mkConfirmPending;\n  window._mkConfirmPending = async function() {\n    const pd = window._mkPending;\n    if (!pd) return;\n    const newName = renameInput.value.trim();\n    if (newName && newName !== pd.lm) {\n      const oldName = pd.lm, wasMove = pd.kind === \'move\';\n      window._mkPending = null;\n      bar.style.display = \'none\';\n      if (wasMove) {\n        await fetch(\'/api/delete_pixel?cam=\' + encodeURIComponent(currentCam) +\n          \'&lm=\' + encodeURIComponent(oldName)).then(r => r.json());\n      }\n      const known = await window._mkLmKnown(newName);\n      const nx = Math.round(pd.px[0] * 10) / 10, ny = Math.round(pd.px[1] * 10) / 10;\n      const res = await fetch(\'/api/add_pixel?cam=\' + encodeURIComponent(currentCam) +\n        \'&lm=\' + encodeURIComponent(newName) + \'&px=\' + nx + \'&py=\' + ny +\n        (known ? \'\' : \'&new=1\')).then(r => r.json());\n      if (res.ok) {\n        window._mkRegisterLm(newName);\n        await loadProjections();\n        if (window._refreshGhosts) window._refreshGhosts();\n        const t = document.getElementById(\'tri-toast\');\n        if (t) {\n          document.getElementById(\'tri-toast-title\').textContent =\n            (wasMove ? oldName + \' → \' : \'\') + newName + \' @ \' + nx + \',\' + ny + \' saved\';\n          document.getElementById(\'tri-toast-meta\').textContent = \'\';\n          t.style.display = \'block\';\n          setTimeout(() => { t.style.display = \'none\'; }, 2600);\n        }\n      } else { alert(res.error || \'rename failed\'); }\n      return;\n    }\n    // nom inchange: flux normal + enregistrer si nouveau\n    const wasNew = pd.isNew, name = pd.lm;\n    await _confirm();\n    if (wasNew) window._mkRegisterLm(name);\n  };\n\n  // helper: le nom existe-t-il deja (serveur ou cree cette session)?\n  let _lmsCache = null;\n  window._mkLmKnown = async function(name) {\n    if (window._mkKnownNew.has(name)) return true;\n    if (_lmsCache === null) {\n      try { _lmsCache = (await fetch(\'/api/all_landmarks\').then(r => r.json())).landmarks || []; }\n      catch (_) { _lmsCache = []; }\n    }\n    return _lmsCache.includes(name);\n  };\n\n  // ── #4: image adjust ──\n  const PARAMS = [\n    [\'exposure\',   -200, 200, 0], [\'highlights\', -100, 100, 0],\n    [\'shadows\',    -100, 100, 0], [\'brightness\', -100, 100, 0],\n    [\'contrast\',   -100, 100, 0], [\'blackpoint\', -100, 100, 0],\n    [\'texture\',       0, 100, 0], [\'clarity\',       0, 100, 0]];\n  const st = Object.fromEntries(PARAMS.map(p => [p[0], p[3]]));\n  const panel = document.getElementById(\'mkadj-panel\');\n  const box = document.getElementById(\'mkadj-sliders\');\n  for (const [k, mn, mx, dv] of PARAMS) {\n    const row = document.createElement(\'div\');\n    row.style.cssText = \'margin-bottom:5px\';\n    row.innerHTML = \'<div style="display:flex;justify-content:space-between;font-size:9.5px;color:var(--mid,#aaa)">\' +\n      \'<span>\' + k + \'</span><span id="mkadj-v-\' + k + \'">\' + dv + \'</span></div>\' +\n      \'<input type="range" id="mkadj-s-\' + k + \'" min="\' + mn + \'" max="\' + mx + \'" value="\' + dv + \'" step="1" \' +\n      \'style="width:100%;height:3px;accent-color:#4ade80">\';\n    box.appendChild(row);\n    document.getElementById(\'mkadj-s-\' + k).addEventListener(\'input\', e => {\n      st[k] = parseFloat(e.target.value);\n      document.getElementById(\'mkadj-v-\' + k).textContent = st[k];\n      applyAdj();\n    });\n  }\n  function toneCurve() {\n    const N = 33, vals = [];\n    const e = Math.pow(2, st.exposure / 200);\n    for (let i = 0; i < N; i++) {\n      let v = i / (N - 1);\n      const bp = st.blackpoint / 400;\n      v = Math.max(0, (v - bp) / Math.max(0.05, 1 - bp));\n      v *= e;\n      v += st.brightness / 350;\n      v = (v - 0.5) * (1 + st.contrast / 130) + 0.5;\n      if (v > 0.55) v = 0.55 + (v - 0.55) * (1 + st.highlights / 160);\n      if (v < 0.45) v = 0.45 - (0.45 - v) * (1 - st.shadows / 160);\n      vals.push(Math.min(1, Math.max(0, v)).toFixed(4));\n    }\n    return vals.join(\' \');\n  }\n  function applyAdj() {\n    const tone = document.getElementById(\'mkadj-tone\');\n    const tv = toneCurve();\n    for (const f of tone.children) f.setAttribute(\'tableValues\', tv);\n    const kt = st.texture / 130, kc = st.clarity / 160;\n    const tex = document.getElementById(\'mkadj-tex\');\n    tex.setAttribute(\'k2\', (1 + kt).toFixed(3)); tex.setAttribute(\'k3\', (-kt).toFixed(3));\n    const cla = document.getElementById(\'mkadj-cla\');\n    cla.setAttribute(\'k2\', (1 + kc).toFixed(3)); cla.setAttribute(\'k3\', (-kc).toFixed(3));\n    const active = PARAMS.some(p => st[p[0]] !== p[3]);\n    frameImg.style.filter = active ? \'url(#mkadj)\' : \'\';\n    window._mkAdjActive = active;\n  }\n  function resetAdj() {\n    for (const [k, , , dv] of PARAMS) {\n      st[k] = dv;\n      document.getElementById(\'mkadj-s-\' + k).value = dv;\n      document.getElementById(\'mkadj-v-\' + k).textContent = dv;\n    }\n    applyAdj();\n  }\n  window._mkAdjToggle = function() {\n    const on = panel.style.display !== \'block\';\n    panel.style.display = on ? \'block\' : \'none\';\n    document.getElementById(\'btn-mkadj\').style.color = on ? \'#4ade80\' : \'#999\';\n    if (!on) resetAdj();   // sortir du mode = image normale\n  };\n  document.getElementById(\'mkadj-close\').addEventListener(\'click\', window._mkAdjToggle);\n  document.getElementById(\'mkadj-reset\').addEventListener(\'click\', resetAdj);\n  window._mkAdjState = st;   // test hook\n  console.log(\'[QOL-V1] rename + fresh cache + image adjust active\');\n})();\n</script>\n' + s[i:]
open(P, 'w').write(s)
print('tools/calib.html: QOL-V1 (rename + cache + adjust)')
print('QOL complet. Redemarre le serveur + hard refresh.')
